def validate(c,d,b):
 e=[];cc=c['cards'];pp=d['pages']
 if len(cc)!=6 or {(x['home']['teamId'],x['away']['teamId']) for x in cc}!=expected:e.append('FIXTURES')
 if len({x[z]['teamId'] for x in cc for z in ['home','away']})!=12:e.append('TWELVE_TEAMS')
 for x in cc:
  if any(x[z]['record']!=st.get(x[z]['teamId']) for z in ['home','away']):e.append('RECORDS')
