  if sc['winning_team_id'] is not None or sc['final_score'] is not None or sc['player_contributors']:e.append('INVENTED_FINAL')
 if len({p['page_id'] for p in pp})!=len(pp):e.append('DUPLICATE_PAGE_ID')
 if {p['matchup_id'] for p in pp if p['matchup_id']}!={x['id'] for x in cc}:e.append('CHAPTER_COVERAGE')
 needed={'cover','opening_drive','scoreboard','sports_player_desk','transactions_waivers','standings_playoffs','power_rankings','week10_preview','pittsys_book','final_word'}
 if not needed<={p['page_role'] for p in pp}:e.append('DEPARTMENT_COVERAGE')
 for i,p in enumerate(pp):
  if not set(required)<=set(p):e.append('PAGE_CONTRACT_FIELDS')
  if p['page_state']!='PLANNED' or p['render_authorized'] or p['actual_winner_team_id'] is not None:e.append('UNAUTHORIZED_PROMOTION')
  if (p['output_width_px'],p['output_height_px'],p['output_aspect_ratio'])!=(1080,1920,'9:16'):e.append('GEOMETRY')
  if p['image_tells']==p['prose_tells']:e.append('REDUNDANT_IMAGE_PROSE')
  if p['adjacent_pages']!={'previous':pp[i-1]['page_id'] if i else None,'next':pp[i+1]['page_id'] if i<len(pp)-1 else None}:e.append('ADJACENCY')
  if any(a['renderer_bound'] for a in p['reference_assets']):e.append('FALSE_REFERENCE_BINDING')
  if p['matchup_id']=='W09-M05' and 'DK_VISUAL_SOURCE_CONFLICT' not in p['failure_conditions']:e.append('DK_FALSE_GREEN')
 if not all(x['presentation_bytes_state']=='MATCH' for x in b['characters']):e.append('PRESENTATION_HASH')
 if len(b['characters'])!=12:e.append('REFERENCE_COVERAGE')
 return sorted(set(e))
