 ('clear_DK_conflict','doc',lambda x:[p['failure_conditions'].remove('DK_VISUAL_SOURCE_CONFLICT') for p in x['pages'] if p['matchup_id']=='W09-M05'])]:
 c,d=copy.deepcopy(cards),copy.deepcopy(doc);mutate(c if kind=='cards' else d);es=validate(c,d,bind);assert es,name;negative.append({'case':name,'rejected_by':es})
